from typing import TypedDict


class ResearchState(TypedDict):
    # User's original business question
    question: str

    # Planner's research tasks
    research_plan: list[str]

    # Targeted web-search queries generated by the planner
    search_queries: list[str]

    # Actual web sources collected by the researcher
    sources: list[dict]

    # Researcher's summarized findings
    research_data: list[str]

    # Analyst's output
    analysis: str

    # Writer's output
    draft_report: str

    # Reviewer's output
    reviewer_feedback: str
    review_score: int
    approved: bool

    # Controls the reviewer -> writer loop
    revision_count: int

    # Final workflow information
    final_report: str
    status: str
